473	+        record('unrecognized_legacy_key_on_test_effect_also_migrates_to_pool', true);
474	+    } else {
475	+        record('unrecognized_legacy_key_on_test_effect_also_migrates_to_pool', false,
476	+            `key=${effect.changes[0].key}`);
477	+    }
478	+});
479	+
480	+// [p2p] A non-test-scoped effect's `data.modifiers` key must NEVER be rewritten, on base OR fix
481	+// -- guards against a bandaid that drops the apply-to scoping and migrates the key everywhere.
482	+await safeAsync('non_test_effect_data_modifiers_key_is_left_alone', () => {
483	+    const effect = makeTestEffect({ applyTo: 'actor', changes: [{ key: 'data.modifiers', mode: CONST.ACTIVE_EFFECT_MODES.CUSTOM, value: '2' }] });
484	+    quiet(() => Migrator.migrate('ActiveEffect', effect));
485	+    if (effect.changes[0].key === 'data.modifiers') {
486	+        record('non_test_effect_data_modifiers_key_is_left_alone', true);
487	+    } else {
488	+        record('non_test_effect_data_modifiers_key_is_left_alone', false, `key changed to ${effect.changes[0].key}`);
489	+    }
490	+});
491	+
492	+// [p2p] An applyTo value that merely LOOKS related ('test', neither 'test_all' nor 'test_item')
493	+// must not trigger the migration -- catches a bandaid that matches applyTo with a substring/
494	+// prefix check (e.g. `applyTo.startsWith('test')`) instead of the exact enum comparison the
495	+// reference fix uses.
496	+await safeAsync('effect_with_similar_but_non_matching_applyto_value_is_left_alone', () => {
497	+    const effect = makeTestEffect({ applyTo: 'test', changes: [{ key: 'data.modifiers', mode: CONST.ACTIVE_EFFECT_MODES.CUSTOM, value: '2' }] });
498	+    quiet(() => Migrator.migrate('ActiveEffect', effect));
499	+    if (effect.changes[0].key === 'data.modifiers') {
500	+        record('effect_with_similar_but_non_matching_applyto_value_is_left_alone', true);
501	+    } else {
502	+        record('effect_with_similar_but_non_matching_applyto_value_is_left_alone', false, `key changed to ${effect.changes[0].key}`);
503	+    }
504	+});
505	+
506	+// [p2p] An unrelated change key on a test-scoped effect is left alone, on base OR fix -- guards
507	+// against a bandaid that keys off applyTo alone and rewrites every change key it finds.
508	+await safeAsync('unrelated_change_key_on_test_effect_is_left_alone', () => {
509	+    const effect = makeTestEffect({ applyTo: 'test_all', changes: [{ key: 'data.threshold', mode: CONST.ACTIVE_EFFECT_MODES.CUSTOM, value: '1' }] });
510	+    quiet(() => Migrator.migrate('ActiveEffect', effect));
511	+    if (effect.changes[0].key === 'data.threshold') {
512	+        record('unrelated_change_key_on_test_effect_is_left_alone', true);
513	+    } else {
514	+        record('unrelated_change_key_on_test_effect_is_left_alone', false, `key changed to ${effect.changes[0].key}`);
515	+    }
516	+});
517	+
518	+// [p2p] An effect already at the current system version is not touched at all -- the generic,
519	+// pre-existing "already up to date" early-return in Migrator.migrate() (unchanged by this fix)
520	+// must survive untouched.
521	+await safeAsync('effect_already_at_current_system_version_is_not_touched_at_all', () => {
522	+    const effect = makeTestEffect({
523	+        applyTo: 'test_all',
524	+        changes: [{ key: 'data.modifiers', mode: CONST.ACTIVE_EFFECT_MODES.CUSTOM, value: '2' }],
525	+        systemVersion: game.system.version,
526	+    });
527	+    const migrated = quiet(() => Migrator.migrate('ActiveEffect', effect));
528	+    if (effect.changes[0].key === 'data.modifiers' && migrated === false) {
529	+        record('effect_already_at_current_system_version_is_not_touched_at_all', true);
530	+    } else {
531	+        record('effect_already_at_current_system_version_is_not_touched_at_all', false,
532	+            `key=${effect.changes[0].key} migrated=${migrated}`);
533	+    }
534	+});
535	+
536	+// [p2p] An older effect (pre-0.31.5) still receives its OWN pre-existing version migration
537	+// (Version0_31_5's `system.force` -> `system.attributes.force` active-effect key rename) --
538	+// guards against a fix that accidentally drops or replaces the rest of Migrator.s_Versions.
539	+// mode is deliberately ADD (not CUSTOM) so Version0_33_0's unrelated CUSTOM-mode migration never
540	+// fires for this fixture, keeping the check isolated to Version0_31_5 alone.
541	+await safeAsync('older_effect_still_receives_pre_existing_version_migrations', () => {
542	+    const effect = makeTestEffect({
543	+        id: 'legacyforce1', name: 'Force Bonus', applyTo: 'actor',
544	+        changes: [{ key: 'system.force', mode: CONST.ACTIVE_EFFECT_MODES.ADD, value: '2' }],
545	+        systemVersion: '0.31.0',
546	+    });
547	+    quiet(() => Migrator.migrate('ActiveEffect', effect));
548	+    if (effect.changes[0].key === 'system.attributes.force') {
549	+        record('older_effect_still_receives_pre_existing_version_migrations', true);
550	+    } else {
551	+        record('older_effect_still_receives_pre_existing_version_migrations', false, `key=${effect.changes[0].key}`);
552	+    }
553	+});
554	+
555	+// [p2p] A test-scoped effect with an empty `changes` array must be left alone without
556	+// throwing -- guards against a fix that indexes `changes[0]` unguarded instead of iterating
557	+// defensively, which would crash on this legitimate (changes-less) effect shape.
558	+await safeAsync('test_scoped_effect_with_no_changes_is_left_alone_without_erroring', () => {
559	+    const effect = makeTestEffect({ applyTo: 'test_all', changes: [] });
560	+    quiet(() => Migrator.migrate('ActiveEffect', effect));
561	+    if (Array.isArray(effect.changes) && effect.changes.length === 0) {
562	+        record('test_scoped_effect_with_no_changes_is_left_alone_without_erroring', true);
563	+    } else {
564	+        record('test_scoped_effect_with_no_changes_is_left_alone_without_erroring', false,
565	+            `changes=${JSON.stringify(effect.changes)}`);
566	+    }
567	+});
568	+
569	+// [p2p] An effect whose change key is ALREADY the modern `data.pool` -- the exact configuration
570	+// this bug report's own screenshot shows -- must be left completely alone: same key, same
571	+// value, still a single change. Guards against an overzealous fix that doesn't recognize
572	+// `data.pool` itself as one of the canonical test fields and "normalizes" it anyway, which is a
573	+// no-op at best and, for a fix that reuses this branch to touch other fields on the same change,
574	+// a silent corruption at worst.
575	+await safeAsync('effect_already_using_modern_pool_key_on_test_effect_is_left_alone', () => {
576	+    const effect = makeTestEffect({
577	+        applyTo: 'test_all',
578	+        changes: [{ key: 'data.pool', mode: CONST.ACTIVE_EFFECT_MODES.CUSTOM, value: '2' }],
579	+    });
580	+    quiet(() => Migrator.migrate('ActiveEffect', effect));
581	+    if (effect.changes.length === 1 && effect.changes[0].key === 'data.pool' && effect.changes[0].value === '2') {
582	+        record('effect_already_using_modern_pool_key_on_test_effect_is_left_alone', true);
583	+    } else {
584	+        record('effect_already_using_modern_pool_key_on_test_effect_is_left_alone', false,
585	+            `changes=${JSON.stringify(effect.changes)}`);
586	+    }
587	+});
588	+
589	+// [p2p] A test-scoped effect legitimately targeting the third canonical field, `data.limit` --
590	+// not just `data.threshold`, which the other canonical-field guard above already covers -- must
591	+// also be left alone. Rounds out the whitelist so a fix can't pass by special-casing only two of
592	+// the three real test fields and normalizing the third one by mistake.
593	+await safeAsync('effect_targeting_canonical_limit_field_on_test_effect_is_left_alone', () => {
594	+    const effect = makeTestEffect({
595	+        applyTo: 'test_item',
596	+        changes: [{ key: 'data.limit', mode: CONST.ACTIVE_EFFECT_MODES.CUSTOM, value: '1' }],
597	+    });
598	+    quiet(() => Migrator.migrate('ActiveEffect', effect));
599	+    if (effect.changes[0].key === 'data.limit') {
600	+        record('effect_targeting_canonical_limit_field_on_test_effect_is_left_alone', true);
601	+    } else {
602	+        record('effect_targeting_canonical_limit_field_on_test_effect_is_left_alone', false,
603	+            `key=${effect.changes[0].key}`);
604	+    }
605	+});
606	+
607	+// ── Report ───────────────────────────────────────────────────────────────────
608	+
609	+writeReport(results);
610	+for (const r of results) {
611	+    console.log(`${r.passed ? 'PASS' : 'FAIL'} ${r.name}${r.passed ? '' : ` — ${r.msg}`}`);
612	+}
613	+const failed = results.filter((r) => !r.passed);
614	+process.exit(failed.length ? 1 : 0);
615	+
616	+// ── Utilities ────────────────────────────────────────────────────────────────
617	+
618	+function writeReport(cases) {
619	+    const failures = cases.filter((c) => !c.passed).length;
620	+    const rows = cases.map((c) => {
621	+        const inner = c.passed ? '' : `\n    <failure message="${esc(c.msg)}">${esc(c.msg)}</failure>`;
622	+        return `  <testcase classname="${SUITE}" name="${esc(c.name)}" time="0">` + inner + `\n  </testcase>`;
623	+    });
624	+    const xml =
625	+        `<?xml version="1.0" encoding="utf-8"?>\n` +
626	+        `<testsuite name="${SUITE}" tests="${cases.length}" ` +
627	+        `failures="${failures}" errors="0" time="1">\n` +
628	+        rows.join('\n') +
629	+        '\n</testsuite>\n';
630	+    mkdirSync(REPORT_DIR, { recursive: true });
631	+    writeFileSync(REPORT, xml, 'utf8');
632	+}
633	+
634	+function esc(s) {
635	+    return String(s ?? '')
636	+        .replace(/&/g, '&amp;')
637	+        .replace(/</g, '&lt;')
638	+        .replace(/>/g, '&gt;')
639	+        .replace(/"/g, '&quot;');
640	+}
641	+
642	+function fatal(msg) {
643	+    const rows = CASE_NAMES.map(
644	+        (name) =>
645	+            `  <testcase classname="${SUITE}" name="${esc(name)}" time="0">\n` +
646	+            `    <error message="${esc(msg)}">${esc(msg)}</error>\n` +
647	+            `  </testcase>`,
648	+    );
649	+    const xml =
650	+        `<?xml version="1.0" encoding="utf-8"?>\n` +
651	+        `<testsuite name="${SUITE}" tests="${CASE_NAMES.length}" ` +
652	+        `failures="${CASE_NAMES.length}" errors="${CASE_NAMES.length}" time="0">\n` +
653	+        rows.join('\n') +
654	+        '\n</testsuite>\n';
655	+    mkdirSync(REPORT_DIR, { recursive: true });
656	+    writeFileSync(REPORT, xml, 'utf8');
657	+    console.error('FATAL:', msg);
658	+    process.exit(2);
659	+}
660

